package cn.balltv.portal;
import java.io.*;import java.util.*;import org.json.*;import org.jsoup.*;import org.jsoup.nodes.*;
/** The website's public fixture feed and current line catalog, not a subscription playlist. */
public final class DamiSource {
 static final String NAME="大米";
 static String base(){return SiteMirrors.base(NAME);}
 static JSONArray catalog(boolean cache)throws Exception{return (JSONArray)HttpData.json(HttpData.get(base()+"/list.json",base()+"/",cache).body);}
 static Feeds.Page fetch(String view,int page)throws Exception{JSONArray lines=catalog(true);String html=HttpData.get(base()+"/?lang=zh-CN",base()+"/",true).body;JSONObject scores=new JSONObject();try{scores=((JSONObject)HttpData.json(HttpData.get(base()+"/api/live-scores.json",base()+"/",true).body)).optJSONObject("scores");}catch(Exception ignored){}List<Feeds.Match> all=parse(html,lines,scores==null?new JSONObject():scores);if(view.equals("live")){ArrayList<Feeds.Match> eligible=new ArrayList<Feeds.Match>();long now=System.currentTimeMillis();for(Feeds.Match m:all)if(LiveState.phase(m,all,now)!=LiveState.Phase.HIDE||m.eventState.equals("finished"))eligible.add(m);all=eligible;Collections.sort(all,(a,b)->Boolean.compare(a.eventState.equals("finished"),b.eventState.equals("finished")));}return MoreSources.page(all,page);}
 public static List<Feeds.Match> parse(String html,JSONArray lineCatalog,JSONObject scores)throws Exception{Map<String,JSONObject> available=new HashMap<String,JSONObject>();for(int i=0;i<lineCatalog.length();i++){JSONObject row=lineCatalog.getJSONObject(i);if(row.optJSONArray("signals")!=null&&row.getJSONArray("signals").length()>0)available.put(row.optString("nami_id"),row);}ArrayList<Feeds.Match> out=new ArrayList<Feeds.Match>();HashSet<String> ids=new HashSet<String>();for(Element card:Jsoup.parse(html).select(".match-card[data-match-id]")){String id=card.attr("data-match-id"),sport=card.attr("data-match-type");if(id.isEmpty()||!ids.add(id)||sport.isEmpty())continue;Feeds.Match m=MoreSources.match(NAME,id);m.home=MoreSources.text(card,".team-home .team-name");m.away=MoreSources.text(card,".team-away .team-name");if(m.home.isEmpty()||m.away.isEmpty())continue;m.sport=sport;m.home=team(m.home,sport);m.away=team(m.away,sport);m.title=m.home+" vs "+m.away;m.league=MoreSources.text(card,".league-badge");long time=Events.epoch(card.attr("data-match-time"));if(time==0)continue;m.time=String.valueOf(time);m.eventState=LiveState.words(MoreSources.text(card,".match-status"));if(m.eventState.isEmpty()&&card.select(".status-live").size()>0)m.eventState="live";if(m.eventState.isEmpty()&&card.hasClass("upcoming"))m.eventState="upcoming";JSONObject score=scores.optJSONObject(id);if(score!=null){String state=LiveState.words(score.optString("status"));if(!state.isEmpty())m.eventState=state;if(score.has("home_score")&&score.has("away_score"))m.score=score.optString("home_score")+" : "+score.optString("away_score");}m.status=m.eventState.isEmpty()?"upcoming":m.eventState;m.room=available.containsKey(id)?id:"";m.raw.put("nami_id",id);MoreSources.pack(m);out.add(m);}return out;}
 static String team(String name,String sport){return name.replaceAll("\\s*[(（]女[)）]$",sport.equals("basketball")?"女篮":"女足");}
 static JSONObject row(JSONArray list,String id)throws Exception{for(int i=0;i<list.length();i++)if(list.getJSONObject(i).optString("nami_id").equals(id))return list.getJSONObject(i);throw new IOException("该赛事已离开当前线路目录");}
 static ArrayList<Feeds.Line> lines(Feeds.Match match)throws Exception{JSONObject row=row(catalog(true),match.id);JSONArray signals=row.getJSONArray("signals");ArrayList<Feeds.Line> out=new ArrayList<Feeds.Line>();for(int i=0;i<signals.length();i++){JSONObject s=signals.getJSONObject(i);String name=s.optString("label","线路"+(i+1)),url=s.optString("url");if(!SourceSafety.promotional(name)&&StreamResolver.direct(url)){Feeds.Line line=new Feeds.Line(name,s.optString("id",String.valueOf(i)),"");line.referer=base()+"/live/"+match.id+".html";out.add(line);}}return out;}
 static String resolve(Feeds.Match match,Feeds.Line line)throws Exception{JSONObject row=row(catalog(RequestBudget.active()),match.id);if(!Events.canonical(team(row.optString("home_team"),match.sport)).equals(Events.canonical(match.home))||!Events.canonical(team(row.optString("away_team"),match.sport)).equals(Events.canonical(match.away))||Math.abs(Events.epoch(row.optString("match_time"))-Events.epoch(match.time))>45*60000L)throw new IOException("赛事资料已变化，请返回刷新");JSONArray signals=row.getJSONArray("signals");for(int i=0;i<signals.length();i++){JSONObject s=signals.getJSONObject(i);if(s.optString("id",String.valueOf(i)).equals(line.id)){String url=s.optString("url");if(!StreamResolver.direct(url)||SourceSafety.promotional(s.optString("label")))throw new IOException("该线路不可用");line.referer=base()+"/live/"+match.id+".html";return url;}}throw new IOException("当前线路已下线");}
}
